    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    top = [x for x, v in enumerate(grid[0]) if v != bg]
    bottom = [x for x, v in enumerate(grid[-1]) if v != bg]
    top_start, bottom_start = min(top), min(bottom)
    for y in range(1, h - 1):
        for x in range(w):
            color = grid[y][x]
            if color == bg:
                continue
            projected_x = top_start + (x - bottom_start)
            if 0 <= projected_x < w:
                for yy in range(1, y + 1):
                    out[yy][projected_x] = color
            for yy in range(y + 1, h - 1):
                out[yy][x] = color
            out[y][x] = 4
    return out

